package io.invenlio.inventory;import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.organization.*;import io.invenlio.warehouse.WarehouseAvailability;import java.math.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class ReservationService{private final AuthorizationService auth;private final AuditTrail audit;private final CatalogInventoryLookup catalog;private final WarehouseAvailability warehouse;private final TraceabilityService trace;private final JdbcTemplate jdbc;private final ApplicationEventPublisher events;ReservationService(AuthorizationService a,AuditTrail au,CatalogInventoryLookup c,WarehouseAvailability w,TraceabilityService t,JdbcTemplate j,ApplicationEventPublisher e){auth=a;audit=au;catalog=c;warehouse=w;trace=t;jdbc=j;events=e;}
 @Transactional ReservationView create(String key,Command c){var a=auth.require(Permission.INVENTORY_RESERVATION_MANAGE);String idem=key==null?"":key.trim();if(idem.isEmpty()||idem.length()>128)throw err("RESERVATION_IDEMPOTENCY_KEY_REQUIRED","Valid Idempotency-Key required");if(!"MANUAL_HOLD".equals(c.referenceType)||c.referenceId==null||c.referenceId.isBlank())throw err("RESERVATION_REFERENCE_REQUIRED","MANUAL_HOLD reference is required");BigDecimal q=quantity(c.quantity);if(c.expiresAt!=null&&!c.expiresAt.isAfter(Instant.now()))throw err("INVALID_RESERVATION_EXPIRY","Expiry must be in the future");String fp=fingerprint(a.tenantId(),c,q);lock(a.tenantId()+":reservation-idem:"+idem);var old=jdbc.query("SELECT id FROM inventory_reservations WHERE tenant_id=? AND idempotency_key=?",(r,n)->(UUID)r.getObject(1),a.tenantId(),idem);if(!old.isEmpty()){String stored=jdbc.queryForObject("SELECT request_fingerprint FROM inventory_reservations WHERE tenant_id=? AND id=?",String.class,a.tenantId(),old.getFirst());if(!stored.equals(fp))throw err("RESERVATION_IDEMPOTENCY_KEY_REUSED","Key used for different reservation");return get(a.tenantId(),old.getFirst());}var v=catalog.findInventoryVariant(a.tenantId(),c.variantId).orElseThrow(()->err("INVENTORY_NOT_RESERVABLE","Variant unavailable"));if(!Set.of("ACTIVE","INACTIVE").contains(v.status()))throw err("INVENTORY_NOT_RESERVABLE","Variant unavailable");if(v.discrete()&&q.stripTrailingZeros().scale()>0)throw err("INVALID_RESERVATION_QUANTITY","Integral unit required");var d=trace.resolve(a.tenantId(),c.variantId,c.lotId,c.serialId,v.trackingMode());if(c.serialId!=null&&q.compareTo(BigDecimal.ONE)!=0)throw err("INVALID_RESERVATION_QUANTITY","Serialized reservation must equal one");var reservable=warehouse.findUsableLocation(a.tenantId(),c.warehouseId,c.locationId).orElseThrow(()->err("INVENTORY_NOT_RESERVABLE","Location unavailable"));if(!Set.of("AISLE","RACK","SHELF","BIN","FLOOR","PALLET_POSITION").contains(reservable.type()))throw err("INVENTORY_NOT_RESERVABLE","Location is not reservable");eligible(a.tenantId(),d);lock(dimension(a.tenantId(),c,d));List<BigDecimal> result=jdbc.query("UPDATE inventory_balances SET reserved_quantity=reserved_quantity+?,updated_at=now(),version=version+1 WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=? AND lot_id IS NOT DISTINCT FROM ? AND serial_id IS NOT DISTINCT FROM ? AND reserved_quantity+?<=on_hand_quantity RETURNING reserved_quantity",(r,n)->r.getBigDecimal(1),q,a.tenantId(),c.variantId,c.warehouseId,c.locationId,d.lotId(),d.serialId(),q);if(result.isEmpty())throw err(c.serialId!=null?"SERIAL_ALREADY_RESERVED":"INSUFFICIENT_AVAILABLE_INVENTORY","Insufficient reservable inventory");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO inventory_reservations(id,tenant_id,reference_type,reference_id,status,requested_quantity,unit_code,expires_at,created_at,created_by,updated_at,version,idempotency_key,request_fingerprint)VALUES (?,?,?,?,'ACTIVE',?,?,?,now(),?,now(),0,?,?)",id,a.tenantId(),c.referenceType,c.referenceId,q,v.baseUnit(),c.expiresAt==null?null:Timestamp.from(c.expiresAt),a.subject(),idem,fp);jdbc.update("INSERT INTO inventory_reservation_allocations(id,tenant_id,reservation_id,variant_id,warehouse_id,location_id,lot_id,serial_id,quantity,unit_code,created_at)VALUES (?,?,?,?,?,?,?,?,?,?,now())",UUID.randomUUID(),a.tenantId(),id,c.variantId,c.warehouseId,c.locationId,d.lotId(),d.serialId(),q,v.baseUnit());audit.record(a,"INVENTORY_RESERVATION_CREATED","inventory-reservation",id.toString());events.publishEvent(new ReservationEvents.InventoryReserved(a.tenantId(),id,c.referenceId));return get(a.tenantId(),id);}
 @Transactional ReservationView release(UUID id){var a=auth.require(Permission.INVENTORY_RESERVATION_MANAGE);var v=get(a.tenantId(),id);if(!v.status.equals("ACTIVE"))return v;releaseLocked(a.tenantId(),id,"RELEASED");audit.record(a,"INVENTORY_RESERVATION_RELEASED","inventory-reservation",id.toString());events.publishEvent(new ReservationEvents.InventoryReservationReleased(a.tenantId(),id));return get(a.tenantId(),id);}
 @Transactional(readOnly=true)ReservationView detail(UUID id){var a=auth.require(Permission.INVENTORY_RESERVATION_READ);return get(a.tenantId(),id);}@Transactional(readOnly=true)List<ReservationView>list(String status,String referenceType,String referenceId,UUID variant,UUID warehouseId,UUID locationId,UUID lot,UUID serial,Instant before,int page,int size,String sort){var a=auth.require(Permission.INVENTORY_RESERVATION_READ);if(page<0||size<1||size>100)throw err("INVALID_PAGINATION","Invalid pagination");String order=switch(sort==null?"createdAt":sort){case"createdAt"->"created_at DESC";case"expiresAt"->"expires_at NULLS LAST";case"status"->"status";default->throw err("INVALID_SORT","Unsupported sort");};return jdbc.query("SELECT id FROM (SELECT DISTINCT r.id,r.created_at,r.expires_at,r.status FROM inventory_reservations r JOIN inventory_reservation_allocations x ON x.tenant_id=r.tenant_id AND x.reservation_id=r.id WHERE r.tenant_id=? AND (?::text IS NULL OR r.status=?::text) AND (?::text IS NULL OR r.reference_type=?::text) AND (?::text IS NULL OR r.reference_id=?::text) AND (?::uuid IS NULL OR x.variant_id=?::uuid) AND (?::uuid IS NULL OR x.warehouse_id=?::uuid) AND (?::uuid IS NULL OR x.location_id=?::uuid) AND (?::uuid IS NULL OR x.lot_id=?::uuid) AND (?::uuid IS NULL OR x.serial_id=?::uuid) AND (?::timestamptz IS NULL OR r.expires_at<=?::timestamptz)) filtered ORDER BY "+order+",id OFFSET ? LIMIT ?",(r,n)->get(a.tenantId(),(UUID)r.getObject(1)),a.tenantId(),status,status,referenceType,referenceType,referenceId,referenceId,variant,variant,warehouseId,warehouseId,locationId,locationId,lot,lot,serial,serial,before,before,page*size,size);}
 @Scheduled(fixedDelayString="${invenlio.inventory.reservation-expiry-interval:PT1M}")@Transactional void expire(){List<UUID> ids=jdbc.query("SELECT id FROM inventory_reservations WHERE status='ACTIVE' AND expires_at<=now() ORDER BY expires_at,id FOR UPDATE SKIP LOCKED LIMIT 100",(r,n)->(UUID)r.getObject(1));for(UUID id:ids){UUID t=jdbc.queryForObject("SELECT tenant_id FROM inventory_reservations WHERE id=?",UUID.class,id);releaseLocked(t,id,"EXPIRED");events.publishEvent(new ReservationEvents.InventoryReservationExpired(t,id));}}
 @Transactional(readOnly=true)Availability availability(UUID variant,UUID warehouse,UUID location,UUID lot,UUID serial){var a=auth.require(Permission.INVENTORY_RESERVATION_READ);String sql="SELECT COALESCE(sum(b.on_hand_quantity),0),COALESCE(sum(b.reserved_quantity),0),COALESCE(sum(b.on_hand_quantity-b.reserved_quantity),0),COALESCE(sum(CASE WHEN v.status='ACTIVE' AND w.status='ACTIVE' AND l.status='ACTIVE' AND l.type IN('AISLE','RACK','SHELF','BIN','FLOOR','PALLET_POSITION') AND (b.lot_id IS NULL OR (il.status='ACTIVE' AND (il.expires_on IS NULL OR il.expires_on>=current_date))) AND (b.serial_id IS NULL OR s.status='ACTIVE') THEN b.on_hand_quantity-b.reserved_quantity ELSE 0 END),0),max(b.unit_code) FROM inventory_balances b JOIN catalog_product_variants v ON v.tenant_id=b.tenant_id AND v.id=b.variant_id JOIN warehouses w ON w.tenant_id=b.tenant_id AND w.id=b.warehouse_id JOIN warehouse_locations l ON l.tenant_id=b.tenant_id AND l.warehouse_id=b.warehouse_id AND l.id=b.location_id LEFT JOIN inventory_lots il ON il.tenant_id=b.tenant_id AND il.id=b.lot_id LEFT JOIN inventory_serials s ON s.tenant_id=b.tenant_id AND s.id=b.serial_id WHERE b.tenant_id=? AND b.variant_id=? AND (?::uuid IS NULL OR b.warehouse_id=?::uuid) AND (?::uuid IS NULL OR b.location_id=?::uuid) AND (?::uuid IS NULL OR b.lot_id=?::uuid) AND (?::uuid IS NULL OR b.serial_id=?::uuid)";return jdbc.query(sql,(r,n)->new Availability(r.getBigDecimal(1),r.getBigDecimal(2),r.getBigDecimal(3),r.getBigDecimal(4),r.getString(5)),a.tenantId(),variant,warehouse,warehouse,location,location,lot,lot,serial,serial).getFirst();}
 @Transactional(readOnly=true)List<Candidate> candidates(UUID variant,UUID warehouse,String requested,int page,int size){var a=auth.require(Permission.INVENTORY_RESERVATION_READ);if(page<0||size<1||size>100)throw err("INVALID_PAGINATION","Invalid pagination");BigDecimal needed=requested==null?null:quantity(requested);String sql="SELECT b.variant_id,b.warehouse_id,b.location_id,b.lot_id,b.serial_id,b.on_hand_quantity,b.reserved_quantity,b.on_hand_quantity-b.reserved_quantity,b.unit_code,il.expires_on,il.lot_number,s.serial_number FROM inventory_balances b JOIN catalog_product_variants v ON v.tenant_id=b.tenant_id AND v.id=b.variant_id JOIN warehouses w ON w.tenant_id=b.tenant_id AND w.id=b.warehouse_id JOIN warehouse_locations l ON l.tenant_id=b.tenant_id AND l.warehouse_id=b.warehouse_id AND l.id=b.location_id LEFT JOIN inventory_lots il ON il.tenant_id=b.tenant_id AND il.id=b.lot_id LEFT JOIN inventory_serials s ON s.tenant_id=b.tenant_id AND s.id=b.serial_id WHERE b.tenant_id=? AND b.variant_id=? AND (?::uuid IS NULL OR b.warehouse_id=?::uuid) AND v.status='ACTIVE' AND w.status='ACTIVE' AND l.status='ACTIVE' AND l.type IN('AISLE','RACK','SHELF','BIN','FLOOR','PALLET_POSITION') AND (b.lot_id IS NULL OR (il.status='ACTIVE' AND (il.expires_on IS NULL OR il.expires_on>=current_date))) AND (b.serial_id IS NULL OR s.status='ACTIVE') AND b.on_hand_quantity>b.reserved_quantity AND (?::numeric IS NULL OR b.on_hand_quantity-b.reserved_quantity>=?::numeric) ORDER BY il.expires_on ASC NULLS LAST,il.normalized_lot_number NULLS LAST,w.normalized_code,l.sequence,l.normalized_code,s.normalized_serial_number NULLS LAST,b.id OFFSET ? LIMIT ?";return jdbc.query(sql,(r,n)->new Candidate((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),r.getBigDecimal(6),r.getBigDecimal(7),r.getBigDecimal(8),r.getString(9),r.getDate(10)==null?null:r.getDate(10).toLocalDate(),r.getString(11),r.getString(12)),a.tenantId(),variant,warehouse,warehouse,needed,needed,page*size,size);}
 @Transactional(readOnly=true)List<ReservationProjectionMismatch> reconciliation(int limit){var a=auth.require(Permission.INVENTORY_RESERVATION_MANAGE);if(limit<1||limit>1000)throw err("INVALID_PAGINATION","Limit must be between 1 and 1000");String sql="WITH authoritative AS (SELECT x.tenant_id,x.variant_id,x.warehouse_id,x.location_id,x.lot_id,x.serial_id,sum(x.quantity) quantity FROM inventory_reservation_allocations x JOIN inventory_reservations r ON r.tenant_id=x.tenant_id AND r.id=x.reservation_id AND r.status='ACTIVE' LEFT JOIN inventory_reservation_consumptions c ON c.tenant_id=x.tenant_id AND c.reservation_allocation_id=x.id WHERE x.tenant_id=? AND c.id IS NULL GROUP BY x.tenant_id,x.variant_id,x.warehouse_id,x.location_id,x.lot_id,x.serial_id) SELECT b.variant_id,b.warehouse_id,b.location_id,b.lot_id,b.serial_id,b.reserved_quantity,COALESCE(a.quantity,0) FROM inventory_balances b LEFT JOIN authoritative a ON a.tenant_id=b.tenant_id AND a.variant_id=b.variant_id AND a.warehouse_id=b.warehouse_id AND a.location_id=b.location_id AND a.lot_id IS NOT DISTINCT FROM b.lot_id AND a.serial_id IS NOT DISTINCT FROM b.serial_id WHERE b.tenant_id=? AND b.reserved_quantity<>COALESCE(a.quantity,0) ORDER BY b.variant_id,b.warehouse_id,b.location_id LIMIT ?";return jdbc.query(sql,(r,n)->new ReservationProjectionMismatch((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),r.getBigDecimal(6),r.getBigDecimal(7)),a.tenantId(),a.tenantId(),limit);}
 private void releaseLocked(UUID t,UUID id,String status){List<UUID> won=jdbc.query("UPDATE inventory_reservations SET status=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND status='ACTIVE' RETURNING id",(r,n)->(UUID)r.getObject(1),status,t,id);if(won.isEmpty())return;List<Allocation> xs=allocations(t,id);for(var x:xs){if(Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM inventory_reservation_consumptions WHERE tenant_id=? AND reservation_allocation_id=?)",Boolean.class,t,x.id)))continue;lock(dimension(t,x));int changed=jdbc.update("UPDATE inventory_balances SET reserved_quantity=reserved_quantity-?,updated_at=now(),version=version+1 WHERE tenant_id=? AND variant_id=? AND warehouse_id=? AND location_id=? AND lot_id IS NOT DISTINCT FROM ? AND serial_id IS NOT DISTINCT FROM ? AND reserved_quantity>=?",x.quantity,t,x.variantId,x.warehouseId,x.locationId,x.lotId,x.serialId,x.quantity);if(changed!=1)throw new IllegalStateException("Reserved projection is inconsistent for reservation "+id);}}
 private ReservationView get(UUID t,UUID id){var rows=jdbc.query("SELECT id,reference_type,reference_id,status,requested_quantity,unit_code,expires_at,created_at,updated_at,version FROM inventory_reservations WHERE tenant_id=? AND id=?",(r,n)->new ReservationView((UUID)r.getObject(1),r.getString(2),r.getString(3),r.getString(4),r.getBigDecimal(5),r.getString(6),r.getTimestamp(7)==null?null:r.getTimestamp(7).toInstant(),r.getTimestamp(8).toInstant(),r.getTimestamp(9).toInstant(),r.getLong(10),allocations(t,id)),t,id);if(rows.isEmpty())throw err("RESERVATION_NOT_FOUND","Reservation not found");return rows.getFirst();}private List<Allocation>allocations(UUID t,UUID id){return jdbc.query("SELECT id,variant_id,warehouse_id,location_id,lot_id,serial_id,quantity,unit_code FROM inventory_reservation_allocations WHERE tenant_id=? AND reservation_id=? ORDER BY id",(r,n)->new Allocation((UUID)r.getObject(1),(UUID)r.getObject(2),(UUID)r.getObject(3),(UUID)r.getObject(4),(UUID)r.getObject(5),(UUID)r.getObject(6),r.getBigDecimal(7),r.getString(8)),t,id);}
 private void eligible(UUID t,TraceabilityService.Resolution d){if(d.lotId()!=null&&jdbc.queryForObject("SELECT count(*) FROM inventory_lots WHERE tenant_id=? AND id=? AND status='ACTIVE' AND (expires_on IS NULL OR expires_on>=current_date)",Integer.class,t,d.lotId())==0)throw err("EXPIRED_LOT_NOT_RESERVABLE","Lot is blocked, archived or expired");if(d.serialId()!=null&&jdbc.queryForObject("SELECT count(*) FROM inventory_serials WHERE tenant_id=? AND id=? AND status='ACTIVE'",Integer.class,t,d.serialId())==0)throw err("INVENTORY_NOT_RESERVABLE","Serial is blocked or archived");}private void lock(String s){jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,s);}private static String dimension(UUID t,Command c,TraceabilityService.Resolution d){return t+":"+c.variantId+":"+c.warehouseId+":"+c.locationId+":"+d.lotId()+":"+d.serialId();}private static String dimension(UUID t,Allocation x){return t+":"+x.variantId+":"+x.warehouseId+":"+x.locationId+":"+x.lotId+":"+x.serialId;}private static BigDecimal quantity(String s){try{BigDecimal q=new BigDecimal(s).stripTrailingZeros();if(q.signum()<=0||q.scale()>6||q.precision()>19)throw new Exception();return q.setScale(6);}catch(Exception e){throw err("INVALID_RESERVATION_QUANTITY","Positive NUMERIC(19,6) required");}}private static String fingerprint(UUID t,Command c,BigDecimal q){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest((t+"|"+c.referenceType+"|"+c.referenceId+"|"+c.variantId+"|"+c.warehouseId+"|"+c.locationId+"|"+c.lotId+"|"+c.serialId+"|"+q+"|"+c.expiresAt).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}private static InventoryException err(String c,String m){return new InventoryException(c,m);}
 record Command(String referenceType,String referenceId,UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,String quantity,Instant expiresAt){}record Allocation(UUID id,UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,BigDecimal quantity,String unitCode){}record ReservationView(UUID id,String referenceType,String referenceId,String status,BigDecimal quantity,String unitCode,Instant expiresAt,Instant createdAt,Instant updatedAt,long version,List<Allocation>allocations){}record Availability(BigDecimal onHand,BigDecimal reserved,BigDecimal available,BigDecimal availableToPromise,String unitCode){}record Candidate(UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,BigDecimal onHand,BigDecimal reserved,BigDecimal available,String unitCode,java.time.LocalDate expiresOn,String lotNumber,String serialNumber){}record ReservationProjectionMismatch(UUID variantId,UUID warehouseId,UUID locationId,UUID lotId,UUID serialId,BigDecimal projectedReserved,BigDecimal authoritativeReserved){}
}
